  1824→      pushkey: pushToken,
  1825→      kind: null, // Setting kind to null removes the pusher
  1826→      app_id: APP_ID,
  1827→    };
  1828→
  1829→    try {
  1830→      const response = await fetch(
  1831→        `${session.homeserverUrl}${MATRIX_ENDPOINTS.PUSHERS_SET}`,
  1832→        {
  1833→          method: "POST",
  1834→          headers: {
  1835→            "Content-Type": "application/json",
  1836→            Authorization: `Bearer ${session.accessToken}`,
  1837→          },
  1838→          body: JSON.stringify(pusherData),
  1839→        },
  1840→      );
  1841→
  1842→      if (!response.ok) {
  1843→        const errorText = await response.text();
  1844→        throw new Error(
  1845→          `Failed to remove pusher: ${response.status} - ${errorText}`,
  1846→        );
  1847→      }
  1848→
  1849→      console.log("Pusher removed successfully from homeserver");
  1850→      return true;
  1851→    } catch (error) {
  1852→      console.error("Failed to remove pusher:", error);
  1853→      throw error;
  1854→    }
  1855→  };
  1856→
  1857→  // PINNED MESSAGES METHODS
  1858→
  1859→  /** Get the list of pinned event IDs for a room */
  1860→  public static getPinnedEventIds = async (
  1861→    roomId: string,
  1862→  ): Promise<string[]> => {
  1863→    if (!this.instance) throw new Error("Client not initialized");
  1864→
  1865→    const room = this.instance.getRoom(roomId);
  1866→    if (!room) throw new Error("Room not found");
  1867→
  1868→    const roomInfo = await room.roomInfo();
  1869→    return roomInfo.pinnedEventIds || [];
  1870→  };
  1871→
  1872→  /** Pin a message in a room */
  1873→  public static pinMessage = async (
  1874→    roomId: string,
  1875→    eventId: string,
  1876→  ): Promise<void> => {
  1877→    if (!this.instance) throw new Error("Client not initialized");
  1878→
  1879→    const room = this.instance.getRoom(roomId);
  1880→    if (!room) throw new Error("Room not found");
  1881→
  1882→    const timeline = await room.timeline();
  1883→    if (!timeline) throw new Error("Timeline not found");
  1884→
  1885→    await timeline.pinEvent(eventId);
  1886→  };
  1887→
  1888→  /** Unpin a message in a room */
  1889→  public static unpinMessage = async (
  1890→    roomId: string,
  1891→    eventId: string,
  1892→  ): Promise<void> => {
  1893→    if (!this.instance) throw new Error("Client not initialized");
  1894→
  1895→    const room = this.instance.getRoom(roomId);
  1896→    if (!room) throw new Error("Room not found");
  1897→
  1898→    const timeline = await room.timeline();
  1899→    if (!timeline) throw new Error("Timeline not found");
  1900→
  1901→    await timeline.unpinEvent(eventId);
  1902→  };
  1903→
  1904→  /** Check if a message is pinned */
  1905→  public static isMessagePinned = async (
  1906→    roomId: string,
  1907→    eventId: string,
  1908→  ): Promise<boolean> => {
  1909→    const pinnedEvents = await this.getPinnedEventIds(roomId);
  1910→    return pinnedEvents.includes(eventId);
  1911→  };
